package sharedkernel

import (
	"fmt"

	"github.com/google/uuid"
)

// ID identifies an aggregate or an event. IDs are UUIDv7, generated by the
// application, never the database, so a retried command produces the same
// IDs. It is an alias, so IDs pass freely to adapters that use uuid.
type ID = uuid.UUID

// NilID is the zero ID: no aggregate.
var NilID ID

// NewID returns a new UUIDv7.
func NewID() (ID, error) {
	id, err := uuid.NewV7()
	if err != nil {
		return NilID, fmt.Errorf("new id: %w", err)
	}

	return id, nil
}

// MustParseID parses a well-known ID, panicking if it is malformed.
func MustParseID(s string) ID { return uuid.MustParse(s) }
